// B14 Bot Health Brief — Aggregate weekly ops stats across the 11-bot suite
const setup = $('Edit Fields — Setup').item.json;
const today = setup['todayDate'];
const weekStart = setup['weekStartIso'];
const lastWeekStart = setup['lastWeekStartIso'];

const trimKeys = (r) => { const o = {}; for (const [k, v] of Object.entries(r || {})) o[k.trim()] = v; return o; };
const inRange = (d, start, end) => { if (!d) return false; const s = String(d).slice(0, 10); return s >= start && s <= end; };
const safeRead = (name) => { try { return $(name).all().map(i => trimKeys(i.json)); } catch (e) { return []; } };

const customers = safeRead('Sheets — Read B2 Customers');
const bookings  = safeRead('Sheets — Read B3 Bookings');
const invoices  = safeRead('Sheets — Read B4 Invoices');
const reacts    = safeRead('Sheets — Read B5 Reactivation Log');
const reps      = safeRead('Sheets — Read B6 Reputation');
const referrals = safeRead('Sheets — Read B7 Referrals');
const tickets   = safeRead('Sheets — Read B9 Tickets');
const lifetime  = safeRead('Sheets — Read B10 Customers');
const ecomm     = safeRead('Sheets — Read B11 E-Comm');
const airbnb    = safeRead('Sheets — Read B11 Airbnb');
const requests  = safeRead('Sheets — Read B11 Requests');

// Per-bot health: best-effort timestamp lookup (try a list of plausible column names per bot)
function botHealth(rows, tsCols, label) {
  // Drop empty-row placeholders (alwaysOutputData emits {} for empty sheets)
  const real = rows.filter(r => Object.values(r || {}).some(v => v !== '' && v != null));
  if (real.length === 0) {
    return { label, rowCount: 0, rowsThisWeek: 0, rowsLastWeek: 0, lastRowAt: null, daysSinceLastFire: null, isSilent: true };
  }
  const tsOf = (r) => {
    for (const c of tsCols) { if (r[c]) return String(r[c]).slice(0, 10); }
    return null;
  };
  const dated = real.map(tsOf).filter(Boolean).sort();
  const lastRowAt = dated.length ? dated[dated.length - 1] : null;
  const rowsThisWeek = real.filter(r => inRange(tsOf(r), weekStart, today)).length;
  const rowsLastWeek = real.filter(r => inRange(tsOf(r), lastWeekStart, weekStart)).length;
  const daysSinceLastFire = lastRowAt ? Math.floor((new Date(today) - new Date(lastRowAt)) / 86400000) : null;
  return {
    label,
    rowCount: real.length,
    rowsThisWeek,
    rowsLastWeek,
    weekTrend: rowsLastWeek > 0 ? Math.round(((rowsThisWeek - rowsLastWeek) / rowsLastWeek) * 100) : (rowsThisWeek > 0 ? 100 : 0),
    lastRowAt,
    daysSinceLastFire,
    isSilent: daysSinceLastFire === null || daysSinceLastFire > 14
  };
}

const health = {
  B2:  botHealth(customers, ['Added At', 'Created At', 'Last Engaged At', 'Last Updated', 'Timestamp'], 'B2 Churn Radar'),
  B3:  botHealth(bookings,  ['Created At', 'Appointment Time', 'Booking Date', 'Last Touch At'],         'B3 No-Show Rescue'),
  B4:  botHealth(invoices,  ['Date Added', 'Created At', 'Date Paid', 'Due Date'],                       'B4 Revenue Recovery'),
  B5:  botHealth(reacts,    ['Sent At', 'Timestamp', 'Created At'],                                       'B5 Reactivation'),
  B6:  botHealth(reps,      ['Triggered At', 'Created At', 'Public Review Sent At'],                      'B6 Reputation Shield'),
  B7:  botHealth(referrals, ['Asked At', 'Converted At', 'Created At', 'Timestamp'],                      'B7 Referral Engine'),
  B9:  botHealth(tickets,   ['Submitted At', 'Resolved At', 'Created At'],                                'B9 Smart Support Triage'),
  B10: botHealth(lifetime,  ['Last Updated', 'Last Purchase Date', 'First Purchase Date'],                'B10 Lifetime & Next Action'),
  B11_EComm:   botHealth(ecomm,    ['Timestamp', 'Logged At', 'Created At'],                              'B11 Review Pro — E-Comm'),
  B11_Airbnb:  botHealth(airbnb,   ['Timestamp', 'Logged At', 'Created At'],                              'B11 Review Pro — Airbnb'),
  B11_Request: botHealth(requests, ['Timestamp', 'Sent At', 'Created At'],                                'B11 Review Request')
};

// Roll-up totals
const allBots = Object.values(health);
const totalEventsWeek = allBots.reduce((s, b) => s + (b.rowsThisWeek || 0), 0);
const totalEventsLastWeek = allBots.reduce((s, b) => s + (b.rowsLastWeek || 0), 0);
const weekTrendOverall = totalEventsLastWeek > 0
  ? Math.round(((totalEventsWeek - totalEventsLastWeek) / totalEventsLastWeek) * 100)
  : (totalEventsWeek > 0 ? 100 : 0);
const silentBots = allBots.filter(b => b.isSilent && b.rowCount > 0).map(b => b.label);
const neverFired = allBots.filter(b => b.rowCount === 0).map(b => b.label);

// Pending operator actions (re-uses B8's surfacing logic — these are the cross-bot todo items)
const stage3 = invoices.filter(r => String(r['Stage'] || '').includes('3') && (r['Status'] === 'Active' || r['Status'] === 'In Progress' || r['Status'] === 'Manual Required'));
const unhappyPending = reps.filter(r => {
  const rating = parseInt(r['Rating']);
  return rating > 0 && rating < 4 && r['Status'] !== 'Resolved' && r['Owner Alerted'] === 'Yes';
});
const noShowsNeedCall = bookings.filter(n => n['No-Show'] === 'Yes' && (!n['Rebooked'] || n['Rebooked'] === 'No'));
const ticketsPending = tickets.filter(t => t['Status'] === 'Open' || t['Status'] === 'In Progress' || (t['Escalate'] === 'Yes' && t['Status'] !== 'Resolved'));

const pending = {
  stage3Count: stage3.length,
  stage3Sum: stage3.reduce((s, r) => s + (parseFloat(String(r['Invoice Amount'] || '0').replace(/[^0-9.-]/g, '')) || 0), 0),
  unhappyPendingCount: unhappyPending.length,
  noShowsNeedCallCount: noShowsNeedCall.length,
  openTicketsCount: ticketsPending.length
};
const totalPendingActions = pending.stage3Count + pending.unhappyPendingCount + pending.noShowsNeedCallCount + pending.openTicketsCount;

// v2: per-promptVersion observability — count uses + parse-success rate by version.
// Reads 'Prompt Version' and 'Parse Success' columns now written by every post-parse Sheets-Log/Update.
const pvAgg = {}; // version -> { uses, successes, sourceBots: Set }
const tally = (rows, botLabel) => {
  for (const r of rows) {
    const v = r['Prompt Version'];
    if (!v) continue;
    if (!pvAgg[v]) pvAgg[v] = { uses: 0, successes: 0, sourceBots: new Set() };
    pvAgg[v].uses += 1;
    const ps = r['Parse Success'];
    if (ps === true || ps === 'TRUE' || ps === 'true' || ps === 'True') pvAgg[v].successes += 1;
    pvAgg[v].sourceBots.add(botLabel);
  }
};
tally(customers, 'B2'); tally(bookings, 'B3'); tally(invoices, 'B4'); tally(reacts, 'B5');
tally(reps, 'B6'); tally(referrals, 'B7'); tally(tickets, 'B9'); tally(lifetime, 'B10');
tally(ecomm, 'B11-EComm'); tally(airbnb, 'B11-Airbnb'); tally(requests, 'B11-Req');

const promptVersionStats = Object.entries(pvAgg).map(([version, a]) => ({
  version,
  uses: a.uses,
  successes: a.successes,
  fallbacks: a.uses - a.successes,
  successRate: a.uses > 0 ? Math.round((a.successes / a.uses) * 100) : null,
  sourceBots: [...a.sourceBots].sort()
})).sort((x, y) => y.uses - x.uses);

const promptVersions = promptVersionStats.map(p => p.version);
const meaningfulSample = promptVersionStats.filter(p => p.uses >= 3);
const worstSuccessRate = meaningfulSample.length > 0
  ? Math.min(...meaningfulSample.map(p => p.successRate))
  : null;
const flaggedPrompts = meaningfulSample.filter(p => p.successRate < 90);

return [{
  json: {
    ...setup,
    health,
    totals: {
      totalEventsWeek,
      totalEventsLastWeek,
      weekTrendOverall,
      silentBots,
      neverFired,
      silentCount: silentBots.length + neverFired.length,
      activeBotCount: allBots.length - silentBots.length - neverFired.length
    },
    pending,
    totalPendingActions,
    promptVersions,
    promptVersionCount: promptVersions.length,
    promptVersionStats,
    worstSuccessRate,
    flaggedPrompts,
    flaggedPromptCount: flaggedPrompts.length
  }
}];

