parameters.jsCode:
const promptVersion = 'b14-health-v2';
const rawText = $input.item.json['rawAIText'] || '';
const d = $('Code — Aggregate Health Stats').item.json;

const cleaned = rawText.replace(/\`\`\`json/g, '').replace(/\`\`\`/g, '').trim();
let parsed;
try { parsed = JSON.parse(cleaned); }
catch (e) {
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = null; } }
}

if (!parsed || !parsed['summary']) {
  const trendArrow = d.totals.weekTrendOverall > 0 ? 'up' : (d.totals.weekTrendOverall < 0 ? 'down' : 'flat');
  parsed = {
    subject: 'Bot Health Brief · Week of ' + d.weekLabel,
    headline: 'Weekly ops summary — ' + d.totals.totalEventsWeek + ' events this week',
    summary: 'The suite processed ' + d.totals.totalEventsWeek + ' events this week (trend ' + trendArrow + ' vs last week). ' +
             d.totals.activeBotCount + ' of 11 bots active. ' + d.totalPendingActions + ' items pending operator attention.',
    actions: [
      d.pending.stage3Count > 0 ? ('Action ' + d.pending.stage3Count + ' stage-3 invoices') : 'No stage-3 invoices outstanding',
      d.pending.unhappyPendingCount > 0 ? ('Follow up with ' + d.pending.unhappyPendingCount + ' unhappy customer(s)') : 'No unhappy customers pending',
      d.totals.silentBots.length > 0 ? ('Investigate silent bot(s): ' + d.totals.silentBots.join(', ')) : 'All bots fired in last 14 days'
    ]
  };
}

const parseSuccess = !!parsed['summary'] && Array.isArray(parsed['actions']);

return {
  ...d, promptVersion,
  subject:  parsed['subject']  || ('Bot Health Brief · Week of ' + d.weekLabel),
  headline: parsed['headline'] || 'Weekly ops summary',
  summary:  parsed['summary'],
  actions:  parsed['actions'] || [],
  parseSuccess
};

// B14 — render the brief as Operator-themed HTML email + a Markdown Telegram twin
const d = $('Code — Parse Brief').item.json;
const fmtR = (n) => 'R' + Math.round(n).toLocaleString('en-ZA');
const trendBadge = (n) => {
  if (n > 0) return '↑ ' + n + '%';
  if (n < 0) return '↓ ' + Math.abs(n) + '%';
  return '→ flat';
};

// Per-bot mini-cards (HTML)
const botCardHtml = (b) => {
  const trend = b.rowsLastWeek > 0 ? trendBadge(b.weekTrend) : (b.rowsThisWeek > 0 ? 'new' : '—');
  const silentTag = b.isSilent && b.rowCount > 0 ? ' <span style="color:#f59e0b">SILENT</span>' : '';
  const newTag = b.rowCount === 0 ? ' <span style="color:#6b6b85">no data yet</span>' : '';
  const lastFireText = b.lastRowAt ? (b.lastRowAt + ' (' + (b.daysSinceLastFire === 0 ? 'today' : b.daysSinceLastFire + 'd ago') + ')') : '—';
  return '<tr style="border-bottom:1px solid #25253a">' +
    '<td style="padding:10px 6px;color:#f5f5fa;font-weight:600">' + b.label + silentTag + newTag + '</td>' +
    '<td style="padding:10px 6px;color:#a8a8c2;text-align:right">' + b.rowsThisWeek + '</td>' +
    '<td style="padding:10px 6px;color:#a8a8c2;text-align:right">' + trend + '</td>' +
    '<td style="padding:10px 6px;color:#6b6b85;text-align:right;font-family:JetBrains Mono,monospace;font-size:12px">' + lastFireText + '</td>' +
  '</tr>';
};

const botRows = Object.values(d.health).map(botCardHtml).join('');

const actionsHtml = d.actions.map((a, i) =>
  '<li style="margin:8px 0;color:#f5f5fa">' + (i + 1) + '. ' + a + '</li>'
).join('');

const trendArrow = d.totals.weekTrendOverall > 0 ? '↑' : (d.totals.weekTrendOverall < 0 ? '↓' : '→');
const trendColor = d.totals.weekTrendOverall > 0 ? '#10b981' : (d.totals.weekTrendOverall < 0 ? '#f43f5e' : '#a8a8c2');

const html =
'<html><body style="margin:0;padding:0;background:#08080c;font-family:-apple-system,Inter,Helvetica,Arial,sans-serif;color:#f5f5fa">' +
'<div style="max-width:640px;margin:0 auto;padding:32px 24px">' +
  '<div style="font-family:JetBrains Mono,monospace;font-size:11px;color:#6366f1;letter-spacing:2px;text-transform:uppercase">// Bot Health Brief · Week of ' + d.weekLabel + '</div>' +
  '<h1 style="font-family:Instrument Serif,Georgia,serif;font-style:italic;font-weight:400;font-size:32px;color:#f5f5fa;margin:8px 0 24px;line-height:1.2">' + d.headline + '</h1>' +
  '<div style="background:#0e0e15;border:1px solid rgba(99,102,241,0.25);border-radius:20px;padding:24px;margin-bottom:24px">' +
    '<div style="font-family:JetBrains Mono,monospace;font-size:10px;color:#6b6b85;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:8px">Headline number</div>' +
    '<div style="font-family:Instrument Serif,Georgia,serif;font-size:54px;color:#f5f5fa;font-weight:400">' + d.totals.totalEventsWeek + ' <span style="font-size:22px;color:' + trendColor + '">' + trendArrow + ' ' + Math.abs(d.totals.weekTrendOverall) + '%</span></div>' +
    '<div style="color:#a8a8c2;font-size:14px;margin-top:6px">events across the suite this week · vs ' + d.totals.totalEventsLastWeek + ' last week</div>' +
  '</div>' +
  '<div style="background:#0e0e15;border:1px solid #25253a;border-radius:20px;padding:20px;margin-bottom:24px">' +
    '<div style="font-family:JetBrains Mono,monospace;font-size:10px;color:#818cf8;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:14px">Executive summary</div>' +
    '<p style="color:#f5f5fa;font-size:15px;line-height:1.6;margin:0">' + d.summary + '</p>' +
  '</div>' +
  (d.actions.length > 0 ? (
    '<div style="background:#0e0e15;border:1px solid rgba(99,102,241,0.25);border-radius:20px;padding:20px;margin-bottom:24px">' +
      '<div style="font-family:JetBrains Mono,monospace;font-size:10px;color:#818cf8;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:14px">Action items · your call</div>' +
      '<ol style="margin:0;padding-left:0;list-style:none">' + actionsHtml + '</ol>' +
    '</div>'
  ) : '') +
  '<div style="background:#0e0e15;border:1px solid #25253a;border-radius:20px;padding:20px;margin-bottom:24px">' +
    '<div style="font-family:JetBrains Mono,monospace;font-size:10px;color:#818cf8;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:14px">Per-bot health</div>' +
    '<table style="width:100%;border-collapse:collapse;font-size:13px">' +
      '<thead><tr style="border-bottom:1px solid rgba(99,102,241,0.25)">' +
        '<th style="text-align:left;padding:6px;color:#6b6b85;font-weight:500;font-family:JetBrains Mono,monospace;font-size:10px;text-transform:uppercase;letter-spacing:1px">Bot</th>' +
        '<th style="text-align:right;padding:6px;color:#6b6b85;font-weight:500;font-family:JetBrains Mono,monospace;font-size:10px;text-transform:uppercase;letter-spacing:1px">Wk</th>' +
        '<th style="text-align:right;padding:6px;color:#6b6b85;font-weight:500;font-family:JetBrains Mono,monospace;font-size:10px;text-transform:uppercase;letter-spacing:1px">Trend</th>' +
        '<th style="text-align:right;padding:6px;color:#6b6b85;font-weight:500;font-family:JetBrains Mono,monospace;font-size:10px;text-transform:uppercase;letter-spacing:1px">Last fired</th>' +
      '</tr></thead><tbody>' + botRows + '</tbody></table>' +
  '</div>' +
  '<div style="background:#0e0e15;border:1px solid #25253a;border-radius:20px;padding:20px;margin-bottom:24px">' +
    '<div style="font-family:JetBrains Mono,monospace;font-size:10px;color:#818cf8;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:14px">Operator queue</div>' +
    '<div style="color:#a8a8c2;font-size:14px;line-height:1.8">' +
      'Stage 3 invoices awaiting manual: <strong style="color:#f5f5fa">' + d.pending.stage3Count + '</strong>' + (d.pending.stage3Sum > 0 ? (' (' + fmtR(d.pending.stage3Sum) + ' at stake)') : '') + '<br>' +
      'Unhappy customers awaiting follow-up: <strong style="color:#f5f5fa">' + d.pending.unhappyPendingCount + '</strong><br>' +
      'No-shows needing personal call: <strong style="color:#f5f5fa">' + d.pending.noShowsNeedCallCount + '</strong><br>' +
      'Open support tickets: <strong style="color:#f5f5fa">' + d.pending.openTicketsCount + '</strong>' +
    '</div>' +
  '</div>' +
  (d.promptVersionStats.length > 0 ? (
    '<div style="background:#0e0e15;border:1px solid #25253a;border-radius:20px;padding:20px;margin-bottom:24px">' +
      '<div style="font-family:JetBrains Mono,monospace;font-size:10px;color:#818cf8;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:14px">Prompt-version observability</div>' +
      '<table style="width:100%;border-collapse:collapse;font-size:12px;font-family:JetBrains Mono,monospace">' +
        '<thead><tr style="border-bottom:1px solid rgba(99,102,241,0.25)">' +
          '<th style="text-align:left;padding:6px;color:#6b6b85;font-weight:500;font-size:10px;text-transform:uppercase;letter-spacing:1px">Version</th>' +
          '<th style="text-align:right;padding:6px;color:#6b6b85;font-weight:500;font-size:10px;text-transform:uppercase;letter-spacing:1px">Uses</th>' +
          '<th style="text-align:right;padding:6px;color:#6b6b85;font-weight:500;font-size:10px;text-transform:uppercase;letter-spacing:1px">Parse OK</th>' +
          '<th style="text-align:right;padding:6px;color:#6b6b85;font-weight:500;font-size:10px;text-transform:uppercase;letter-spacing:1px">Rate</th>' +
        '</tr></thead><tbody>' +
        d.promptVersionStats.map(p => {
          const rateColor = p.successRate === null ? '#6b6b85' : (p.successRate >= 90 ? '#10b981' : (p.successRate >= 75 ? '#f59e0b' : '#f43f5e'));
          const rateText = p.successRate === null ? '—' : (p.successRate + '%');
          return '<tr style="border-bottom:1px solid #25253a">' +
            '<td style="padding:8px 6px;color:#f5f5fa">' + p.version + '</td>' +
            '<td style="padding:8px 6px;color:#a8a8c2;text-align:right">' + p.uses + '</td>' +
            '<td style="padding:8px 6px;color:#a8a8c2;text-align:right">' + p.successes + '</td>' +
            '<td style="padding:8px 6px;text-align:right;color:' + rateColor + ';font-weight:600">' + rateText + '</td>' +
          '</tr>';
        }).join('') +
      '</tbody></table>' +
      (d.flaggedPromptCount > 0 ? ('<div style="margin-top:12px;padding:10px;background:rgba(244,63,94,0.08);border:1px solid rgba(244,63,94,0.3);border-radius:8px;color:#f43f5e;font-size:12px">⚠ ' + d.flaggedPromptCount + ' prompt(s) flagged — parse-success below 90%. Consider retuning or bumping the version.</div>') : '') +
    '</div>'
  ) : '') +
  '<div style="text-align:center;margin-top:32px;padding-top:20px;border-top:1px solid #25253a;color:#6b6b85;font-size:11px;font-family:JetBrains Mono,monospace;letter-spacing:1px">' +
    'NSM · Built in Joburg · Prompt: ' + d.promptVersion +
  '</div>' +
'</div></body></html>';

// Telegram twin — short Markdown summary
const tgLines = [];
tgLines.push('*Bot Health Brief — ' + d.weekLabel + '*');
tgLines.push('');
tgLines.push(trendArrow + ' *' + d.totals.totalEventsWeek + '* events this week (' + (d.totals.weekTrendOverall >= 0 ? '+' : '') + d.totals.weekTrendOverall + '% vs last)');
tgLines.push('');
tgLines.push('_' + d.summary + '_');
if (d.actions.length > 0) {
  tgLines.push('');
  tgLines.push('*Actions:*');
  d.actions.forEach((a, i) => tgLines.push((i + 1) + '. ' + a));
}
if (d.flaggedPromptCount > 0) {
  tgLines.push('');
  tgLines.push('⚠️ Flagged prompts (parse <90%): ' + d.flaggedPrompts.map(p => p.version + ' ' + p.successRate + '%').join(', '));
}
if (d.totals.silentBots.length > 0) {
  tgLines.push('');
  tgLines.push('🟡 Silent: ' + d.totals.silentBots.join(', '));
}
tgLines.push('');
tgLines.push('_Prompt: ' + d.promptVersion + '_');

return {
  ...d,
  html,
  telegramText: tgLines.join('\n')
};

